CustomField.formula:
IF(
    /* --- PATH 1: Use manual hours only when > 0 --- */
    Submit_Hours__c > 0,

    /* Convert manual hours → H MM */
    TEXT(
        FLOOR( Submit_Hours__c )
    ) &
    " H " &
    RIGHT(
        "00" &
        TEXT(
            ROUND(
                MOD( Submit_Hours__c * 60, 60 ),
                0
            )
        ),
        2
    ) &
    "M",

    /* --- PATH 2: Your original Start/End formula --- */
    IF(
        ISBLANK(End_Time__c),
        "",
        TEXT(
            FLOOR(
                MAX(
                    0,
                    ROUND(
                        ((End_Time__c - Start_Time__c) * 1440) - (Paused_Seconds__c / 60),
                        0
                    )
                ) / 60
            )
        ) &
        " H " &
        RIGHT(
            "00" &
            TEXT(
                MOD(
                    MAX(
                        0,
                        ROUND(
                            ((End_Time__c - Start_Time__c) * 1440) - (Paused_Seconds__c / 60),
                            0
                        )
                    ),
                    60
                )
            )
        ,
        2
        ) &
        "M"
    )
)
